 sealed class PickerWindow:IWin32Window{readonly IntPtr handle;public PickerWindow(IntPtr value){handle=value;}public IntPtr Handle{get{return handle;}}}
 static DialogResult ShowProjectDialog(FileDialog dialog){
  // A native dialog must be owned by the editor, not by a hidden launcher-thread form.
  IntPtr foreground=GetForegroundWindow();var title=new StringBuilder(512);GetWindowText(foreground,title,title.Capacity);
  string caption=title.ToString();
  if(foreground!=IntPtr.Zero&&IsWindowVisible(foreground)&&caption.IndexOf("StarForge",StringComparison.OrdinalIgnoreCase)>=0&&caption.IndexOf("Launcher",StringComparison.OrdinalIgnoreCase)<0)
   return dialog.ShowDialog(new PickerWindow(foreground));
  // Detached panels or a focus change may leave no editor HWND available. Keep a
  // transparent topmost owner visible for the full dialog lifetime; Hide loses its z-order.
  using(var owner=new Form{Width=1,Height=1,ShowInTaskbar=false,TopMost=true,Opacity=0,FormBorderStyle=FormBorderStyle.None,StartPosition=FormStartPosition.CenterScreen}){
   owner.Show();owner.Activate();owner.BringToFront();return dialog.ShowDialog(owner);
  }
 }

